"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3986],{57857:e=>{e.exports=JSON.parse('{"functions":[{"name":"get","desc":"Returns the player\'s overhead display, or `nil` if they have no character or it\\nhas not been created yet.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"BillboardGui?"}],"function_type":"static","source":{"line":65,"path":"src/Shared/Class/PlayerOverhead.luau"}},{"name":"set","desc":"Changes one property of the display. Does nothing when the display does not exist,\\nor when `value` is not the type the setting expects.\\n\\n- `\\"color\\"` \u2014 a [Color3] for the username text.\\n- `\\"visible\\"` \u2014 a boolean toggling the whole billboard.\\n\\n:::caution The \\"name\\" setting does not work\\n`\\"name\\"` is guarded by `typeof(value) == \\"boolean\\"` and then assigned straight to\\nthe label\'s `Text`, so a string name is rejected and only a boolean would get\\nthrough \u2014 which is not a valid `Text` value. Set `username.Text` directly instead.\\n:::","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"setting","desc":"`\\"color\\"` or `\\"visible\\"`","lua_type":"string"},{"name":"value","desc":"Value matching the setting","lua_type":"Color3 | boolean?"}],"returns":[],"function_type":"static","source":{"line":91,"path":"src/Shared/Class/PlayerOverhead.luau"}},{"name":"getTeamColor","desc":"Reads the team color from a `Team.Username` label inside the display, falling back\\nto white.\\n\\n:::note Requires a custom overhead\\n[PlayerOverhead.create] does not build a `Team` child, so with the display this\\nmodule makes, this always returns the white default. It is here for projects that\\nreplace the overhead with their own asset containing that label.\\n:::","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"Color3"}],"function_type":"static","source":{"line":124,"path":"src/Shared/Class/PlayerOverhead.luau"}},{"name":"setNameStyle","desc":"Applies the player\'s equipped title and nametag (their `EquippedTitle` /\\n`EquippedNametag` attributes, published by CosmeticService): the title in\\nthe row above the username, the nametag as a gradient on it. Does nothing\\nwhen the display does not exist; [PlayerOverhead.create] calls it for\\nevery new display.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":233,"path":"src/Shared/Class/PlayerOverhead.luau"}},{"name":"create","desc":"Builds the overhead display on the player\'s current character.\\n\\nReturns silently if the character has no `HumanoidRootPart` yet \u2014 wait for the\\ncharacter to load before calling. Calling twice leaves two billboards, so remove\\nthe old one first if you are rebuilding it.\\n\\n```lua\\nplayer.CharacterAdded:Connect(function(character)\\n\\tcharacter:WaitForChild(\\"HumanoidRootPart\\")\\n\\tPlayerOverhead.create(player)\\nend)\\n```","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":263,"path":"src/Shared/Class/PlayerOverhead.luau"}}],"properties":[],"types":[],"name":"PlayerOverhead","desc":"Creates and tweaks the name display floating above a player\'s character.\\n\\nThe display is a [BillboardGui] named `OverheadDisplay` parented to the character,\\nso it is destroyed automatically on respawn \u2014 call [PlayerOverhead.create] again\\nfrom a `CharacterAdded` handler.\\n\\nThe username is tinted by the player\'s user level: premium yellow, moderator blue,\\nsuperuser orange, creator red, and plain white for everyone else.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","source":{"line":16,"path":"src/Shared/Class/PlayerOverhead.luau"}}')}}]);